typedef struct ShellMenu{IContextMenu iface;LONG refs;HWND owner;UINT count;WCHAR *paths;} ShellMenu;
static const char *verbs[]={"open","cut","copy","delete","properties","restore"};
static const char *labels[]={"&Open","Cu&t","&Copy","&Delete","&Properties","Restore last deleted item"};
static const char *help[]={"Open the selected items","Cut the selected items to the clipboard","Copy the selected items to the clipboard","Move the selected items to the recovery store","Show file information","Restore the most recently deleted item"};
